import {kinds,themes,colors,categories,slots,rules,day,dateOf,shift,level,stage,uid,fresh,achievements,weeklyCount} from './core.js';
import {items,stories,destinations,prompts,emotions,moods,relaxations} from './data.js';
import {load,transact,restore,backup,rawState} from './storage.js';
import {icon,pet,scene,escape as e,itemColors} from './art.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toast=document.querySelector('#toast');
let s,tab=['home','travel','care','shop','insights','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'home',busy=false,toastTimer,modalType='',modalData={},month=day().slice(0,7),selectedDay=day(),range=7,shopMode='shop',shopSlot='',taskCategory='',journalFilter='',registration,installed=false;
let activatingUpdate=false,queued=Promise.resolve(),journalSearch='';
let channel;try{channel=new BroadcastChannel('mooslicht-web');channel.onmessage=async()=>{try{s=await load();render()}catch(error){notify(error.message)}}}catch{}
const nav=[['home','Zuhause','home'],['travel','Reisen','map'],['care','Für mich','heart'],['shop','Atelier','bag'],['insights','Rückblick','chart']];
const journalKinds={journal:'Tagebuch',gratitude:'Dankbarkeit',reflection:'Reflexion'};
const dateLabel=k=>dateOf(k)?.toLocaleDateString('de-DE',{day:'numeric',month:'long',year:'numeric'})||k;
const btn=(label,action,more='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${more}>${label}</button>`;
const empty=(title,text,ic='leaf')=>`<div class="empty">${icon(ic,31)}<h3>${title}</h3><p class="small">${text}</p></div>`;
const field=(label,input)=>`<label class="field">${label}${input}</label>`;
const select=(name,options,value,attrs='')=>`<select name="${name}" ${attrs}>${Object.entries(options).map(([id,label])=>`<option value="${id}" ${String(value)===id?'selected':''}>${e(label)}</option>`).join('')}</select>`;
const progress=(value,max,label)=>`<div class="progress" role="progressbar" aria-label="${e(label)}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.min(value,max)}"><span style="width:${Math.min(100,Math.max(0,value/max*100))}%"></span></div>`;
const tasksOn=k=>s.occurrences.filter(o=>o.day===k).sort((a,b)=>Number(a.done)-Number(b.done)||b.priority-a.priority||(a.time||'99').localeCompare(b.time||'99'));
const appearance=()=>{document.documentElement.dataset.theme=s.profile.theme;document.documentElement.dataset.mode=s.profile.appearance==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):s.profile.appearance;document.querySelector('meta[name=theme-color]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()};
function notify(text){clearTimeout(toastTimer);toast.textContent=text;toast.classList.add('visible');toastTimer=setTimeout(()=>toast.classList.remove('visible'),4000)}
function run(action,options={}){const next=queued.then(()=>executeAction(action,options));queued=next.catch(()=>{});return next}
async function executeAction(action,{quiet=false}={}){
 busy=true;
 try{const result=await transact(action);s=result.state;appearance();render();channel?.postMessage(s.revision);if(!quiet)notify(result.message);return true}
 catch(error){const target=modal.open?modal.querySelector('.form-error'):null;if(target)target.textContent=error.message;else notify(error.message);return false}finally{busy=false}
}
function navigate(next){tab=next;history.replaceState(null,'','#'+tab);render();window.scrollTo({top:0,behavior:'instant'})}
function render(){
 if(!s)return;appearance();if(!s.profile.onboarded){app.innerHTML=onboarding();return}
 const greeting=s.profile.userName?`Hallo, ${e(s.profile.userName)}.`:'Schön, dass du da bist.';
 app.innerHTML=`<a class="skip" href="#main">Zum Inhalt</a><div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('leaf',25)}</span>mooslicht</div><p class="brand-sub">Kleine Schritte. Große Nähe.</p><nav class="nav" aria-label="Hauptnavigation">${nav.map(([id,label,ic])=>`<button type="button" data-action="nav" data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('heart',20)}Du musst nicht alles schaffen.<br>Ein kleiner Schritt reicht.</div><button class="sidebar-settings" data-action="nav" data-tab="settings">${icon('settings',19)}Profil & Einstellungen</button></div></aside><main class="content" id="main"><header class="topbar"><div><div class="mobile-brand">${icon('leaf',15)} MOOSLICHT</div><div class="greeting-date">${new Date().toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long'})}</div><h1>${tab==='home'?greeting:({travel:'Eine Welt für euch.',care:'Ein Moment für dich.',shop:'Ein Zuhause wie du.',insights:'Was schon gewachsen ist.',settings:'Ganz in deinem Tempo.'}[tab])}</h1></div><div class="header-right"><span class="pill">${icon('coin',17)} ${s.coins} Münzen</span><button class="icon-btn" data-action="nav" data-tab="settings" aria-label="Einstellungen">${icon('settings')}</button><div class="circle-avatar">${pet(s.profile)}</div></div></header>${registration?.waiting?`<div class="update-banner">Eine neue Mooslicht-Version ist bereit.${btn('Jetzt laden','update','','small')}</div>`:''}${({home:home,travel:travel,care:care,shop:shop,insights:insights,settings:settings}[tab])()}<div class="tiny-note">Mit Liebe zu kleinen Schritten. <span class="offline"><i></i><span id="connection">${navigator.onLine?'Auf diesem Gerät gespeichert':'Offline · dein Zuhause bleibt bei dir'}</span></span></div></main></div>`;
 if(tab==='home'){
  const add=app.querySelector('.add-task');
  if(add){const overdue=s.occurrences.filter(o=>!o.done&&o.day<day()&&s.tasks.some(t=>t.id===o.taskID&&t.rule==='once'&&!t.archived&&!t.paused&&t.startsOn===o.day));
   if(overdue.length)add.insertAdjacentHTML('beforebegin',`<h3>Noch offen · ohne Druck</h3>${overdue.map(o=>taskRow(o,true)).join('')}`);
   add.insertAdjacentHTML('afterend',btn('Ideen für meinen Alltag '+icon('leaf',16),'templates','','ghost small'));
  }
 }
 tick();
}
function onboarding(){return `<main class="onboarding"><div class="brand"><span class="brand-mark">${icon('leaf',25)}</span>mooslicht</div><div class="welcome"><div class="welcome-intro"><span class="eyebrow">Ein kleiner Freund für deinen Alltag</span><h1>Ein Zuhause.<br>Ein Freund.<br>Dein eigenes Tempo.</h1><p>Du kümmerst dich um dich. Dein Begleiter wächst mit dir – mit kleinen Schritten, sanften Pausen und einer Prise Abenteuer.</p><div id="custom-preview">${scene(s)}</div><p class="help">Deine Einträge bleiben auf diesem Gerät. Kostenlos, ohne Konto oder Werbung.</p></div><form class="card stack" data-form="onboard"><div><h2>Wer begleitet dich?</h2><p class="help">Alles lässt sich später ändern.</p></div>${customFields(s.profile)}${field('Dein Name <span class="help">(optional)</span>',`<input name="userName" maxlength="40" autocomplete="given-name" placeholder="Wie darf ich dich nennen?">`)}<div class="notice">Wir beginnen mit drei kleinen Ideen: Wasser trinken, durchatmen und etwas Freundliches für dich tun. Du kannst sie jederzeit verändern.</div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Unser Zuhause öffnen ${icon('arrow',18)}</button></form></div></main>`}
function customFields(p){return `<input type="hidden" name="kind" value="${p.kind}"><input type="hidden" name="theme" value="${p.theme}"><input type="hidden" name="color" value="${p.color}">${field('Name deines Begleiters',`<input name="petName" value="${e(p.petName)}" maxlength="30" required autocomplete="off">`)}<div class="species">${Object.entries(kinds).map(([id,label])=>`<button type="button" data-action="custom-choice" data-name="kind" data-value="${id}" class="${p.kind===id?'selected':''}" aria-label="${label}" aria-pressed="${p.kind===id}">${pet({...p,kind:id})}<span>${label}</span></button>`).join('')}</div><div class="form-section"><h3>Deine Fellfarbe</h3><div class="swatches">${Object.entries(colors).map(([id,label])=>`<button type="button" data-action="custom-choice" data-name="color" data-value="${id}" class="${p.color===id?'selected':''}" style="background:${{pink:'#e9a8c2',honey:'#d4a16e',cream:'#efdbba',mint:'#afcdb8',lavender:'#c1a7da',cocoa:'#ac7d64'}[id]}" aria-label="${label}" aria-pressed="${p.color===id}"></button>`).join('')}</div></div>${field('Ein kleines Detail',select('pattern',{plain:'Pur',heart:'Herzchen',freckles:'Sommersprossen'},p.pattern,'data-preview'))}<div class="form-section"><h3>Deine Farbwelt</h3><div class="theme-grid">${Object.entries(themes).map(([id,label])=>`<button type="button" class="theme-option ${p.theme===id?'selected':''}" data-action="custom-choice" data-name="theme" data-value="${id}" aria-pressed="${p.theme===id}"><i style="background:${{rose:'#f3cadd',moss:'#c8dfbe',lavender:'#d8c7ed',sky:'#c0dfea'}[id]}"></i>${label}</button>`).join('')}</div></div>`}
function taskRow(o,showDate=false){return `<div class="task-row ${o.done?'done':''}"><button class="task-toggle" data-action="task-toggle" data-id="${e(o.id)}" aria-label="${e(o.title)}, ${o.done?'erledigt':'offen'}" aria-pressed="${o.done}" ${o.day>day()?'disabled':''}><span class="checkbox">${o.done?icon('check',17):''}</span><span><span class="task-title">${e(o.title)}</span><span class="task-meta"><span>${e(categories[o.category])}</span>${o.time?`<span>· ${e(o.time)}</span>`:''}${showDate?`<span>· ${dateLabel(o.day)}</span>`:''}${o.priority===2?`<span>${icon('star',11)} Wichtig</span>`:''}</span></span></button><button class="icon-btn" data-action="task-edit" data-id="${e(o.taskID)}" aria-label="${e(o.title)} bearbeiten">${icon('edit',16)}</button></div>`}
function home(){const list=tasksOn(day()),done=list.filter(o=>o.done).length,trip=s.adventures.find(t=>!t.claimed),mood=s.moods.find(m=>m.day===day());return `<div class="home-grid"><div class="stack"><section class="card pet-card"><button type="button" class="scene-button" data-action="pet" aria-label="Mit ${e(s.profile.petName)} spielen" style="display:block;width:100%;padding:0;border:0;background:none">${scene(s)}</button><div class="pet-info"><div class="row between"><div><div class="eyebrow">Dein kleiner Begleiter</div><h2 class="pet-name">${e(s.profile.petName)} ${icon('heart',17)}</h2><span class="muted small">${stage(s)} · Level ${level(s)}</span></div>${btn(icon('edit',16)+' Gestalten','customize','','small')}</div><div class="statbar"><div class="stat"><span class="value">${icon('bolt',18)} ${s.energy}<small>/60</small></span><div class="label">Energie</div></div><div class="stat"><span class="value">${icon('coin',18)} ${s.coins}</span><div class="label">Münzen</div></div><div class="stat"><span class="value">${icon('star',18)} ${s.xp}</span><div class="label">Erfahrung</div></div></div><div class="xp-line"><span>Gemeinsam wachsen</span><span>${s.xp%100} / 100 XP bis Level ${level(s)+1}</span></div>${progress(s.xp%100,100,'Erfahrung zum nächsten Level')}</div></section><div class="quote">${icon('leaf',22)}<span>Du darfst langsam wachsen.<br>Dein Begleiter geht mit dir.</span></div><section class="card"><div class="row between"><span class="pill plain">${icon('map',17)} Kleine Abenteuer</span>${btn(icon('arrow',17),'nav','data-tab="travel" aria-label="Zu Reisen"','ghost')}</div><h3 style="margin:13px 0 7px">${trip?'Die Welt ist voller kleiner Wunder.':s.energy>=30?'Bereit für eure nächste Entdeckung?':'Ein bisschen Energie für neue Wege.'}</h3><p class="small muted">${trip?'Dein Begleiter bringt eine Geschichte mit nach Hause.':s.energy>=30?'30 Energie, ein neuer Weg und eine Geschichte nur für euch.':'Deine kleinen Schritte sammeln Energie für gemeinsame Reisen.'}</p>${trip?`<div style="margin-top:15px" data-trip-progress="${trip.id}">${progress(Math.max(0,Date.now()-trip.start),trip.end-trip.start,'Reisefortschritt')}</div>`:''}</section></div><div class="stack right-column"><section class="card stack"><div class="row between"><div><span class="eyebrow">Kleine Schritte zählen</span><h2>Dein Tag</h2></div><span class="pill plain">${done} / ${list.length}</span></div>${progress(done,Math.max(1,list.length),'Erledigte Aufgaben heute')}<div class="task-list">${list.length?list.map(o=>taskRow(o)).join(''):empty('Ein bisschen Platz für dich','Wähle einen kleinen Schritt, der dir guttut.')}</div><button class="add-task" data-action="task-new">${icon('plus',18)} Einen kleinen Schritt hinzufügen</button>${btn('Alle Aufgaben verwalten '+icon('arrow',14),'manage-tasks','','ghost small')}</section><section class="card stack"><div class="row between"><div><h3>Wie geht es dir gerade?</h3><p class="help">Jedes Gefühl darf da sein.</p></div>${icon('sun',22)}</div><div class="mood-mini">${moods.map((label,i)=>`<button data-action="mood" data-value="${i+1}" aria-label="${label}" title="${label}">${moodFace(i+1)}</button>`).join('')}</div>${mood?`<span class="help">Heute: ${e(moods[mood.value-1])}. Du kannst das jederzeit ändern.</span>`:''}</section><section class="card soft stack"><div class="row">${icon('wind',27)}<div><h3>Eine Pause ist auch ein Schritt.</h3><p class="help">Nur du. Ein Atemzug. Ein Moment.</p></div></div>${btn('Eine Atempause nehmen '+icon('arrow',16),'practice','data-kind="breathing"','small')}</section><section class="card install-card">${icon('download',24)}<div><h3>Ein Platz auf deinem iPhone</h3><p class="help">Dein Zuhause, nur einen Tipp entfernt.</p></div>${btn('So geht’s','install','','small')}</section></div></div>`}
function moodFace(value){const mouth=value<3?'M9 17q3-4 6 0':value===3?'M9 16h6':'M9 15q3 5 6 0';return `<svg viewBox="0 0 24 24" width="29" height="29" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="9"/><circle cx="9" cy="10" r=".7" fill="currentColor"/><circle cx="15" cy="10" r=".7" fill="currentColor"/><path d="${mouth}" stroke-linecap="round"/></svg>`}
function travel(){const trip=s.adventures.find(t=>!t.claimed);return `<div class="stack"><div class="page-heading"><p>Ein neuer Weg. Ein bisschen Neugier. Eine Erinnerung, die bleibt.</p></div>${trip?`<div class="two-col"><div>${scene(s,{action:Date.now()<trip.end?'walk':'happy',destination:trip.destination})}</div><div class="card stack">${Date.now()<trip.end?`<span class="eyebrow">Dein Begleiter ist unterwegs</span><h2>Ein kleiner Weg, viele Wunder.</h2><div data-trip-progress="${trip.id}">${progress(Date.now()-trip.start,trip.end-trip.start,'Reisefortschritt')}</div><p class="clock" data-trip-time="${trip.id}"></p><p class="muted small">Du darfst die App schließen. Die Reise läuft weiter, und die Geschichte wartet auf dich.</p><div data-trip-ready class="hidden">${btn('Die Geschichte öffnen','refresh','','primary')}</div>`:storyChoice(trip)}</div></div>`:`<div class="row wrap"><span class="pill">${icon('bolt',16)} ${s.energy}/60 Energie</span><span class="help">Eine Reise pro Tag · 30 Energie · die erste Reise dauert eine Minute</span></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${destinations.map((d,i)=>`<section class="card travel-card"><div class="travel-art">${icon(['leaf','wind','star'][i],60)}</div><div class="travel-detail stack"><span class="eyebrow">${level(s)<d.level?'Ab Level '+d.level:'Bereit für Entdeckungen'}</span><div><h2>${d.title}</h2><p class="help">${d.subtitle}</p></div>${btn('Auf Entdeckungsreise '+icon('arrow',16),'travel-start',`data-id="${d.id}" ${level(s)<d.level||s.energy<30||s.adventures.some(t=>t.day===day())?'disabled':''}`,'primary')}</div></section>`).join('')}</div>${s.adventures.some(t=>t.day===day())?'<p class="notice">Heute habt ihr schon eine Reise begonnen. Morgen wartet eine neue Geschichte. Deine Energie bleibt erhalten.</p>':''}`}<div class="section-head"><div><span class="eyebrow">Gesammelte Erinnerungen</span><h2>Euer Entdeckungsalbum</h2></div><span class="pill plain">${s.adventures.filter(t=>t.claimed).length} Entdeckungen</span></div><div class="album">${s.adventures.filter(t=>t.claimed).reverse().map(t=>{const story=stories.find(x=>x.id===t.story);return `<article class="card"><span class="pill plain">${icon('star',15)} ${e(story.discovery)}</span><h3 style="margin-top:13px">${e(story.title)}</h3><p>${e(story.responses[t.choice])}</p><small class="muted">${dateLabel(t.day)}</small></article>`}).join('')||empty('Die erste Geschichte wartet','Nach eurer Reise findest du hier eure gemeinsamen Erinnerungen.','book')}</div></div>`}
function storyChoice(t){const story=stories.find(x=>x.id===t.story);return `<span class="eyebrow">Wieder zu Hause · eine Geschichte für dich</span><h2>${e(story.title)}</h2><p class="story">${e(story.text)}</p>${story.choices.map((label,i)=>btn(e(label),'travel-claim',`data-id="${t.id}" data-choice="${i}"`)).join('')}<p class="help">Beide Antworten führen zu einer Entdeckung. Es gibt kein Richtig oder Falsch.</p>`}
function care(){return `<div class="stack"><p class="muted page-heading">Was du gerade brauchst, darf ganz klein sein.</p><div class="two-col"><div class="stack"><section class="card soft stack"><span class="eyebrow">Alles darf da sein</span><h2>Du musst dich nicht besser fühlen,<br>um gut zu dir zu sein.</h2><p class="small muted">Ein ehrlicher Moment ist genug. Jede Stimmung zählt gleich.</p>${btn('Meine Stimmung festhalten '+icon('heart',17),'mood','','primary')}</section><div class="option-list">${Object.entries(journalKinds).map(([id,title])=>tile(title,id==='journal'?'Deine Gedanken haben hier Platz':'Ein freundlicher Blick auf deinen Tag',id==='gratitude'?'sun':'book','journal-new',`data-kind="${id}"`)).join('')}${tile('Meine Einträge',`${s.journals.length} persönliche Gedanken`,'book','journal-list')}</div></div><div class="stack"><div class="option-list">${tile('Ruhig atmen','Eine, drei oder fünf Minuten','wind','practice','data-kind="breathing"')}${tile('Eine Sache nach der anderen','Fokus mit Pause und Fortsetzen','timer','practice','data-kind="focus"')}${relaxations.map((r,i)=>tile(r.title,'Eine kleine angeleitete Pause','leaf','relax',`data-index="${i}"`)).join('')}${tile('Was mir wichtig ist','Deine persönlichen Wochenziele','flag','goals')}</div><p class="help">Übungen sind freiwillige Alltagspausen. Du kannst sie jederzeit beenden. Für jede Aktivitätsart gibt es einmal pro Tag eine kleine Belohnung.</p></div></div></div>`}
function tile(title,subtitle,ic,action,attrs=''){return `<button class="option" data-action="${action}" ${attrs}><span class="tile-icon">${icon(ic,24)}</span><span class="grow"><strong>${e(title)}</strong><small>${e(subtitle)}</small></span>${icon('arrow',17)}</button>`}
function itemArt(i){if(['head','neck','outfit'].includes(i.slot))return `<div class="item-art">${pet(s.profile,{[i.slot]:i.id})}</div>`;return `<div class="item-art" style="color:${itemColors[i.variant]}">${icon({wall:'home',floor:'moon',bed:'moon',plant:'leaf',lamp:'sun',ornament:'heart'}[i.slot],48)}<span class="item-dot"></span></div>`}
function shop(){let list=items.filter(i=>(!shopSlot||i.slot===shopSlot)&&(shopMode==='shop'||s.owned.includes(i.id)));return `<div class="stack"><div class="two-col"><div>${scene(s)}</div><section class="card stack"><span class="eyebrow">Dein Atelier</span><h2>Ein Lieblingsplatz.<br>Ganz nach eurem Geschmack.</h2><p class="small muted">Kleine Fundstücke, weiche Kissen und ein bisschen Zauber. Alles bleibt verfügbar, bis du bereit bist.</p><div class="row wrap"><span class="pill">${icon('coin',17)} ${s.coins} Münzen</span><span class="pill plain">${s.owned.length} Lieblingsstücke</span></div>${btn(icon('edit',17)+' Tier & Farbwelt gestalten','customize')}</section></div><div class="row wrap between"><div class="segmented" aria-label="Atelier-Bereich"><button data-action="shop-mode" data-mode="shop" class="${shopMode==='shop'?'active':''}">Shop</button><button data-action="shop-mode" data-mode="inventory" class="${shopMode==='inventory'?'active':''}">Mein Inventar</button></div><label class="field"><span class="visually-hidden">Gegenstandskategorie</span>${select('slot',{'':'Alle Kategorien',...slots},shopSlot,'data-filter="shop"')}</label></div><div class="grid">${list.map(i=>`<button class="card item-card" data-action="item" data-id="${i.id}">${itemArt(i)}${s.equipped[i.slot]===i.id?`<span class="badge">${icon('check',15)}</span>`:''}<h3>${i.name}</h3><small class="muted">${slots[i.slot]} · ${i.price>=100?'Zauberhaft':i.price>=50?'Besonders':'Vertraut'}</small><div class="price">${s.equipped[i.slot]===i.id?'Ausgewählt':s.owned.includes(i.id)?'Gehört dir':i.price+' Münzen · Level '+i.level}</div></button>`).join('')}</div><p class="help center">Mit deinen kleinen Schritten verdient. Keine Echtgeldkäufe.</p></div>`}
function insights(){const completed=s.occurrences.filter(o=>o.done),monthStart=month+'-01',start=dateOf(monthStart),leading=(start.getDay()+6)%7,daysInMonth=new Date(start.getFullYear(),start.getMonth()+1,0).getDate(),chartDays=Array.from({length:range},(_,i)=>shift(day(),i-range+1)),max=Math.max(1,...chartDays.map(k=>tasksOn(k).filter(o=>o.done).length));return `<div class="stack"><p class="muted page-heading">Jeder Schritt gehört zu dir. Auch die leisen.</p><div class="statbar" style="margin-top:0"><div class="card stat"><div class="value">${completed.length}</div><div class="label">Kleine Schritte</div></div><div class="card stat"><div class="value">${new Set(completed.map(o=>o.day)).size}</div><div class="label">Aktive Tage</div></div><div class="card stat"><div class="value">${s.adventures.filter(t=>t.claimed).length}</div><div class="label">Entdeckungen</div></div></div><div class="two-col"><section class="card stack"><div class="row between"><button class="icon-btn" data-action="month" data-delta="-1" aria-label="Vorheriger Monat">‹</button><h3>${start.toLocaleDateString('de-DE',{month:'long',year:'numeric'})}</h3><button class="icon-btn" data-action="month" data-delta="1" aria-label="Nächster Monat">›</button></div><div class="calendar">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(k=>`<span class="weekday">${k}</span>`).join('')}${Array.from({length:leading},()=>'<span></span>').join('')}${Array.from({length:daysInMonth},(_,i)=>{let k=month+'-'+String(i+1).padStart(2,'0'),count=tasksOn(k).filter(o=>o.done).length;return `<button data-action="select-day" data-day="${k}" class="${selectedDay===k?'selected':''}" aria-label="${dateLabel(k)}, ${count} erledigt">${i+1}${count?'<i></i>':''}</button>`}).join('')}</div><div class="section-head"><h3>${dateLabel(selectedDay)}</h3><span class="pill plain">${tasksOn(selectedDay).filter(o=>o.done).length} erledigt</span></div><div class="task-list">${tasksOn(selectedDay).map(o=>taskRow(o)).join('')||'<p class="help">Für diesen Tag sind keine Schritte geplant.</p>'}</div>${s.moods.some(m=>m.day===selectedDay)?`<p class="notice">Stimmung: ${e(moods[s.moods.find(m=>m.day===selectedDay).value-1])}</p>`:''}<p class="help">Vergangene Abschlüsse kannst du ergänzen. Sie verändern die Historie, vergeben aber keine Spielbelohnung.</p></section><div class="stack"><section class="card stack"><div class="row between"><h3>Deine kleinen Schritte</h3><div class="segmented"><button data-action="range" data-range="7" class="${range===7?'active':''}">Woche</button><button data-action="range" data-range="30" class="${range===30?'active':''}">Monat</button></div></div><div class="chart" role="img" aria-label="Erledigte Aufgaben in den letzten ${range} Tagen">${chartDays.map((k,i)=>{let count=tasksOn(k).filter(o=>o.done).length;return `<div class="chart-col" title="${dateLabel(k)}: ${count}"><small>${count||''}</small><div class="chart-bar" style="height:${count/max*110+3}px"></div>${range===7||i%7===0?`<span>${dateOf(k).getDate()}.</span>`:''}</div>`}).join('')}</div><p class="help">${chartDays.reduce((n,k)=>n+tasksOn(k).filter(o=>o.done).length,0)} erledigte Schritte in ${range} Tagen.</p></section><section class="card stack"><h3>Dein Stimmungsverlauf</h3>${s.moods.filter(m=>chartDays.includes(m.day)).sort((a,b)=>a.day.localeCompare(b.day)).map(m=>`<div class="row"><span style="color:var(--accent)">${moodFace(m.value)}</span><div class="grow"><strong class="small">${moods[m.value-1]}</strong><div class="help">${dateLabel(m.day)} · ${e(m.emotions.join(', '))}</div></div></div>`).join('')||'<p class="help">Dein erster Check-in gibt diesem Verlauf einen Anfang.</p>'}</section></div></div><div class="section-head"><div><span class="eyebrow">Kleine Meilensteine</span><h2>Das habt ihr erlebt</h2></div></div><div class="milestones">${achievements(s).map(([id,label,got])=>`<div class="card milestone ${got?'':'locked'}">${icon(got?'star':'leaf',25)}<span>${label}${got?' · erreicht':''}</span></div>`).join('')}</div>${btn('Belohnungen nachvollziehen '+icon('arrow',17),'ledger')}</div>`}
function settings(){return `<div class="stack"><p class="muted page-heading">Dein Zuhause darf sich so anfühlen, wie du es brauchst.</p><div class="two-col"><div class="stack"><section class="card stack"><h2>Dein Profil</h2><form data-form="settings" class="stack">${field('Dein Name',`<input name="userName" value="${e(s.profile.userName)}" maxlength="40" autocomplete="given-name">`)}${field('Erscheinungsbild',select('appearance',{system:'Wie mein Gerät',light:'Hell',dark:'Dunkel'},s.profile.appearance))}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">Einstellungen speichern</button></form>${btn('Tier, Fellfarbe & Umgebung','customize')}</section><section class="card stack"><h2>Deine Daten gehören dir.</h2><p class="small muted">Aufgaben, Spielstand und persönliche Einträge bleiben auf diesem Gerät. Es gibt kein Konto, keinen App-Server und keine Analyse-Dienste.</p><div class="notice">Erstelle regelmäßig eine Sicherungsdatei. Wenn du Browserdaten löschst oder das Gerät wechselst, kannst du damit alles wiederherstellen. Die Datei enthält auch deine persönlichen Texte.</div>${btn(icon('download',17)+' Sicherungsdatei herunterladen','export')}${btn(icon('upload',17)+' Sicherung wiederherstellen','import')}<input id="backup-file" type="file" accept=".json,application/json" hidden>${btn('Dauerhafte Speicherung anfragen','persist','','small')}<p id="storage-state" class="help">Browser entscheiden, ob dauerhafte Speicherung möglich ist. Eine eigene Sicherung bleibt sinnvoll.</p></section></div><div class="stack"><section class="card stack"><h2>Ein Platz auf dem Home-Bildschirm</h2><p class="small muted">Wie eine App starten, nach dem ersten Laden auch offline. Ohne Mac und ohne wöchentliche Erneuerung.</p>${btn('Installationshilfe öffnen','install')}</section><section class="card stack"><h2>Freundliche Erinnerungen</h2><p class="small muted">Zeitgebundene Aufgaben werden bei geöffneter App angekündigt. Für eine Erinnerung bei geschlossener App kannst du eine Aufgabe in deinen Kalender übernehmen.</p>${btn('Aufgaben & Kalenderexport','manage-tasks')}<p class="help">Ein später bearbeiteter oder gelöschter Termin muss auch im Kalender angepasst werden. Ohne Server bietet diese Version keine Push-Mitteilungen bei geschlossener App.</p></section><section class="card stack"><h2>Ein bewusster Neuanfang</h2><p class="small muted">Dein Tier bleibt auch an Pausentagen gern bei dir. Falls du wirklich neu beginnen möchtest, kannst du die lokalen Daten nach Bestätigung löschen.</p>${btn('Alle lokalen Daten löschen','reset','','danger')}</section><p class="help">Mooslicht Web 1.0 · Deutsch<br>Keine Werbung, keine Käufe, keine kostenpflichtigen Server.<br>Die Übungen sind Alltagspausen, keine medizinische Behandlung.</p></div></div></div>`}
function dialog(title,html,type='',data={}){modalType=type;modalData=data;modal.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Schließen">${icon('close',20)}</button></header><div class="dialog-content stack">${html}<div class="form-error" role="alert"></div></div>`;if(!modal.open)modal.showModal();tick()}
async function closeModal(){if(modalType==='timer'&&modalData.kind==='breathing'){const t=s.sessions.find(t=>t.kind==='breathing'&&!t.finished&&t.remaining===null);if(t)await run({type:'session-pause',id:t.id},{quiet:true})}modal.close();modalType='';appearance()}
function showCustom(){dialog('Ganz dein Stil',`<div id="custom-preview" class="custom-preview">${scene(s)}</div><form data-form="customize" class="stack">${customFields(s.profile)}<div class="form-error" role="alert"></div><button type="submit" class="btn primary full">Diesen Look speichern</button></form>`,'customize')}
function showTask(id,preset){const t=s.tasks.find(t=>t.id===id)||{id:uid(),title:'',category:'care',rule:'daily',weekdays:[1],startsOn:day(),priority:1,time:'',paused:false,archived:false,reminder:false,...preset};dialog(id?'Dein kleiner Schritt':'Ein kleiner Schritt',`<form data-form="task" class="stack" data-id="${t.id}">${field('Was möchtest du tun?',`<input name="title" value="${e(t.title)}" maxlength="140" required placeholder="Zum Beispiel: ein Glas Wasser trinken">`)}<div class="form-grid">${field('Kategorie',select('category',categories,t.category))}${field('Priorität',select('priority',{0:'In Ruhe',1:'Normal',2:'Wichtig'},t.priority))}</div><div class="form-grid">${field('Ab wann?',`<input type="date" name="startsOn" value="${t.startsOn}" required>`)}${field('Wiederholung',select('rule',rules,t.rule,'data-rule'))}</div><div id="weekday-field" class="${['weekly','weekdays'].includes(t.rule)?'':'hidden'}"><p class="small">Wochentage <span class="help">(wöchentlich: einen auswählen)</span></p><div class="weekdays">${['So','Mo','Di','Mi','Do','Fr','Sa'].map((label,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${t.weekdays.includes(i)?'checked':''}>${label}</label>`).join('')}</div></div>${field('Uhrzeit <span class="help">(optional)</span>',`<input type="time" name="time" value="${t.time}">`)}<label class="check"><input type="checkbox" name="reminder" ${t.reminder?'checked':''}>Bei geöffneter App daran erinnern</label><label class="check"><input type="checkbox" name="paused" ${t.paused?'checked':''}>Aufgabe pausieren</label><p class="help">Änderungen gelten für offene heutige und zukünftige Fälligkeiten. Vergangene Erfolge bleiben erhalten.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">Schritt speichern</button>${id?`<div class="row wrap">${btn(icon('calendar',17)+' In Kalender übernehmen','calendar-export',`data-id="${t.id}"`,'small')}${btn('Aufgabe löschen','task-delete',`data-id="${t.id}"`,'small danger')}</div>`:''}</form>`,'task')}
function manageTasks(){dialog('Deine Aufgaben',`<div class="row wrap">${btn(icon('plus',17)+' Neuer Schritt','task-new','','primary')}${select('category',{'':'Alle Kategorien',...categories},taskCategory,'data-filter="tasks" aria-label="Aufgabenkategorie"')}</div><div class="stack">${s.tasks.filter(t=>!t.archived&&(!taskCategory||t.category===taskCategory)).map(t=>`<div class="card stack"><div><h3>${e(t.title)}</h3><span class="help">${categories[t.category]} · ${t.paused?'Pausiert':rules[t.rule]}</span></div><div class="row wrap">${btn('Bearbeiten','task-edit',`data-id="${t.id}"`,'small')}${btn(t.paused?'Fortsetzen':'Pausieren','task-pause',`data-id="${t.id}"`,'small')}${btn(icon('calendar',17),'calendar-export',`data-id="${t.id}" aria-label="Kalenderexport für ${e(t.title)}"`,'small')}</div></div>`).join('')||empty('Noch Platz für kleine Schritte','Erstelle eine Aufgabe, die zu dir passt.')}</div>`,'manage-tasks')}
function showMood(value){const m=s.moods.find(m=>m.day===day()),v=value||m?.value||3;dialog('Wie geht es dir gerade?',`<p class="muted small">Du musst nichts erklären. Wähle, was am ehesten passt.</p><form data-form="mood" class="stack"><input type="hidden" name="value" value="${v}"><div class="option-list">${moods.map((label,i)=>`<button type="button" data-action="mood-choice" data-value="${i+1}" class="option ${v===i+1?'selected':''}" aria-pressed="${v===i+1}">${moodFace(i+1)}<strong>${label}</strong></button>`).join('')}</div><h3>Gefühle, die dich begleiten <span class="help">(optional)</span></h3><div class="form-grid">${emotions.map(label=>`<label class="check"><input type="checkbox" name="emotion" value="${label}" ${m?.emotions.includes(label)?'checked':''}>${label}</label>`).join('')}</div><p class="help">Alle Gefühle erhalten dieselbe Belohnung. Änderungen bleiben ohne zusätzliche Vergütung möglich.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">Für heute festhalten</button></form>`,'mood')}
function journalEditor(id,kind='journal'){const entry=s.journals.find(x=>x.id===id)||{id:'',kind,text:'',prompt:kind==='journal'?'':prompts[Math.floor(Math.random()*prompts.length)]};dialog(journalKinds[entry.kind],`<form class="stack" data-form="journal" data-id="${entry.id}">${field('Art deines Eintrags',select('kind',journalKinds,entry.kind))}<input type="hidden" name="prompt" value="${e(entry.prompt)}"><p class="notice ${entry.prompt?'':'hidden'}" id="journal-prompt">${e(entry.prompt)}</p>${btn('Eine neue Reflexionsfrage','prompt','','small')}${field('Nur für dich',`<textarea name="text" maxlength="20000" required placeholder="Was möchtest du festhalten?">${e(entry.text)}</textarea>`)}<p class="help">Deine Texte werden lokal gespeichert und nicht versendet.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary full">Eintrag speichern</button></form>`,'journal')}
function journalList(){dialog('Deine Gedanken',`<div class="row wrap">${btn(icon('plus',17)+' Neuer Eintrag','journal-new','','primary')}${select('kind',{'':'Alle Einträge',...journalKinds},journalFilter,'data-filter="journal" aria-label="Eintragsart"')}</div>${field('Einträge durchsuchen',`<input type="search" name="journalSearch" value="${e(journalSearch)}" placeholder="Ein Wort, ein Gedanke …">`)}<div id="journal-entries" class="stack" aria-live="polite">${journalEntries()}</div>`,'journal-list')}

function showPractice(kind){const t=s.sessions.find(t=>t.kind===kind&&!t.finished);dialog(kind==='breathing'?'Eine Atempause':'Deine Fokuszeit',t?`<div class="timer-orb ${kind==='breathing'&&t.remaining===null?'inhale':''}"><div class="timer-text">${icon(kind==='breathing'?'wind':'timer',30)}<strong data-phase="${t.id}">${t.remaining!==null?'Pause':kind==='breathing'?'Einatmen':'Eine Sache nach der anderen'}</strong><span class="clock" data-session-time="${t.id}"></span></div></div><div class="stack"><button class="btn primary full" data-action="session-pause" data-id="${t.id}" data-session-pause>${icon(t.remaining===null?'moon':'arrow',18)} ${t.remaining===null?'Pause':'Fortsetzen'}</button><button class="btn primary full hidden" data-action="session-finish" data-id="${t.id}" data-session-finish>Diesen Moment mitnehmen</button>${btn('Für heute beenden','session-cancel',`data-id="${t.id}"`)}</div><p class="help">${kind==='breathing'?'Atme nur so, wie es sich angenehm anfühlt. Die Übung pausiert, wenn du sie verlässt oder die App in den Hintergrund wechselst.':'Die Fokuszeit läuft auch bei geschlossener App weiter. Du kannst sie jederzeit pausieren.'}</p>`:`<div class="timer-orb"><div class="timer-text">${icon(kind==='breathing'?'wind':'timer',45)}<strong>Ein bisschen Zeit für dich.</strong></div></div><form data-form="practice" data-kind="${kind}" class="stack">${field('Wie viel Zeit möchtest du dir schenken?',select('minutes',Object.fromEntries((kind==='breathing'?[1,3,5]:[5,15,25,45]).map(n=>[n,n+' Minuten'])),kind==='breathing'?1:5))}<button type="submit" class="btn primary full">Meine Zeit beginnt</button></form><p class="help">Du kannst jederzeit abbrechen. Eine vollständige Übung erhält einmal pro Tag eine kleine Belohnung.</p>`,'timer',{kind})}
function showRelax(index,step=0){const r=relaxations[index];dialog(r.title,`<div class="timer-orb" style="width:160px;height:160px">${icon('leaf',53)}</div><span class="eyebrow">Schritt ${step+1} von ${r.steps.length}</span><p class="story">${r.steps[step]}</p>${btn(step===r.steps.length-1?'Diesen Moment mitnehmen':'In meinem Tempo weiter','relax-next',`data-index="${index}" data-step="${step}"`,'primary full')}${step?btn('Einen Schritt zurück','relax-back',`data-index="${index}" data-step="${step}"`):''}${btn('Für heute beenden','close')}`,'relax',{index,step})}
function goals(){dialog('Was dir wichtig ist',`<p class="help">Passende Aufgaben zählen automatisch für die aktuelle Woche. Kein Abzug, wenn dein Ziel offen bleibt.</p>${s.goals.map(g=>`<section class="card stack"><h3>${e(g.title)}</h3><p class="help">${categories[g.category]} · ${weeklyCount(s,g)} von ${g.target} Schritten</p>${progress(weeklyCount(s,g),g.target,g.title)}${btn('Anpassen','goal-edit',`data-id="${g.id}"`,'small')}</section>`).join('')||empty('Eine Richtung für deine Woche','Wähle, was du stärken möchtest.','flag')}${btn(icon('plus',17)+' Ein Wochenziel wählen','goal-new','','primary')}`,'goals')}
function goalEditor(id){const g=s.goals.find(g=>g.id===id)||{id:uid(),title:'',category:'care',target:3};dialog('Dein Wochenziel',`<form data-form="goal" data-id="${g.id}" class="stack">${field('Was möchtest du stärken?',`<input name="title" value="${e(g.title)}" maxlength="100" required>`)}${field('Kategorie',select('category',categories,g.category))}${field('Schritte pro Woche',`<input name="target" type="number" min="1" max="50" value="${g.target}" required>`)}<div class="form-error" role="alert"></div><button type="submit" class="btn primary full">Wochenziel speichern</button>${id?btn('Ziel entfernen','goal-delete',`data-id="${g.id}"`,'danger'):''}</form>`,'goal')}
const templates=[['Fünf Minuten frische Luft','movement'],['Ein Glas Wasser trinken','care'],['Einen lieben Menschen kontaktieren','connection'],['Eine kleine Ecke aufräumen','home'],['Etwas Neues lesen','growth'],['Bildschirmpause machen','care'],['Schultern lockern','movement'],['Den Tag freundlich abschließen','care']];
function showTemplates(){dialog('Kleine Ideen für deinen Alltag',`<p class="help">Wähle eine Idee und passe sie an dein Leben an. Erst mit „Schritt speichern“ wird sie zu deiner Aufgabe.</p><div class="option-list">${templates.map(([title,cat],index)=>tile(title,categories[cat],'leaf','template',`data-index="${index}"`)).join('')}</div>`,'templates')}
function journalEntries(){const query=journalSearch.toLocaleLowerCase('de');return s.journals.filter(x=>(!journalFilter||x.kind===journalFilter)&&(!query||(x.text+' '+x.prompt).toLocaleLowerCase('de').includes(query))).sort((a,b)=>b.date-a.date).map(x=>`<article class="card journal-card"><span class="eyebrow">${journalKinds[x.kind]} · ${dateLabel(x.day)}</span><p class="journal-preview" style="margin-top:10px">${e(x.text)}</p><div class="row">${btn('Bearbeiten','journal-edit',`data-id="${x.id}"`,'small')}${btn('Löschen','journal-delete',`data-id="${x.id}"`,'small danger')}</div></article>`).join('')||empty('Hier ist gerade noch Platz',query?'Kein Eintrag passt zu deiner Suche.':'Dein erster Eintrag darf ganz kurz sein.','book')}
function showItem(id){const i=items.find(x=>x.id===id),owned=s.owned.includes(id),equipped={...s.equipped,[i.slot]:id};dialog('Ein neues Lieblingsstück',`${scene(s,{equipped})}<div><span class="eyebrow">${slots[i.slot]} · ${i.price>=100?'Zauberhaft':i.price>=50?'Besonders':'Vertraut'}</span><h2>${i.name}</h2></div><p class="help">So könnte es bei euch aussehen. Deine Vorschau ändert noch nichts.</p>${owned?`${btn('Jetzt verwenden','equip',`data-id="${id}"`,'primary full')}${['head','neck','outfit'].includes(i.slot)&&s.equipped[i.slot]===id?btn('Ablegen','unequip',`data-slot="${i.slot}"`):''}`:`<p class="small muted">Dein Guthaben: ${s.coins} Münzen · ab Level ${i.level}</p>${btn('Für '+i.price+' Münzen kaufen','buy',`data-id="${id}" ${s.coins<i.price||level(s)<i.level?'disabled':''}`,'primary full')}${s.coins<i.price?`<p class="help">Noch ${i.price-s.coins} Münzen. Der Gegenstand wartet auf dich.</p>`:''}${level(s)<i.level?`<p class="help">Auf Level ${i.level} wird dieses Stück freigeschaltet.</p>`:''}`}`,'item',{id})}
function ledger(){dialog('Deine Belohnungen',`<p class="notice">Aufgabe: +10 XP, +5 Münzen und bis zu +10 Energie. Aktivität: einmal pro Tag und Art +5 XP, +3 Münzen und bis zu +5 Energie. Reise: +30 XP und +20 Münzen. Energie ist auf 60 begrenzt.</p>${s.ledger.slice().reverse().map(x=>`<div class="card"><strong>${e(x.label)}</strong><p class="help">${new Date(x.date).toLocaleString('de-DE')}</p><p class="small">${x.xp} XP · ${x.coins} Münzen · ${x.energy} Energie</p></div>`).join('')||empty('Jeder kleine Schritt zählt','Hier findest du bald eure ersten Belohnungen.')}`,'ledger')}
function installHelp(){dialog('Mooslicht wie eine App',`<div class="row">${icon('download',35)}<p>Dein kleiner Rückzugsort auf dem Home-Bildschirm.</p></div><div class="notice"><strong>Auf dem iPhone</strong><p>1. Diesen Link in Safari öffnen.<br>2. Auf „Teilen“ tippen.<br>3. „Zum Home-Bildschirm“ wählen.<br>4. Mit „Hinzufügen“ bestätigen.</p></div><p class="small muted">Auf Android und am Computer findest du „App installieren“ im Browsermenü. Nach dem ersten vollständigen Laden ist Mooslicht offline nutzbar.</p><p class="help">Dein Spielstand liegt im Speicher dieses Browsers bzw. dieser installierten Web-App. Sichere ihn vor einem Geräte- oder Browserwechsel in den Einstellungen. Es gibt keine automatische Synchronisierung zwischen Geräten.</p><span id="offline-status" class="pill plain">${installed?'Offline-Dateien bereit':'Offline-Dateien werden beim ersten Laden vorbereitet'}</span>`,'install')}
function preview(form){const d=new FormData(form),p={...s.profile};for(const k of ['kind','theme','color','pattern','petName'])p[k]=String(d.get(k)||s.profile[k]);document.documentElement.dataset.theme=p.theme;const container=document.querySelector('#custom-preview');if(container)container.innerHTML=scene(s,{profile:p});for(const b of form.querySelectorAll('[data-action="custom-choice"]')){const chosen=p[b.dataset.name]===b.dataset.value;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen))}}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function calendarExport(t){if(!t.time){notify('Lege zuerst eine Uhrzeit für diese Aufgabe fest.');return}if(t.archived||t.paused){notify('Setze die Aufgabe zuerst fort.');return}const clean=x=>String(x).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let start=t.startsOn<day()?day():t.startsOn;if(['weekly','weekdays'].includes(t.rule))while(!t.weekdays.includes(dateOf(start).getDay()))start=shift(start,1);const date=start.replaceAll('-','')+'T'+t.time.replace(':','')+'00',week=['SU','MO','TU','WE','TH','FR','SA'];let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Mooslicht//Selfcare//DE','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+t.id+'@mooslicht','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+date,'DURATION:PT5M','SUMMARY:'+clean(t.title),'DESCRIPTION:Ein kleiner Schritt für dich. Termine werden im Kalender eigenständig verwaltet.'];if(t.rule==='daily')lines.push('RRULE:FREQ=DAILY');else if(['weekly','weekdays'].includes(t.rule))lines.push('RRULE:FREQ=WEEKLY;BYDAY='+t.weekdays.map(i=>week[i]).join(','));lines.push('BEGIN:VALARM','TRIGGER:PT0S','ACTION:DISPLAY','DESCRIPTION:Zeit für einen kleinen Schritt','END:VALARM','END:VEVENT','END:VCALENDAR');download(lines.join('\r\n'),'Mooslicht-Termin.ics','text/calendar;charset=utf-8')}
document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,kind}=b.dataset;
 try{switch(action){
 case 'nav':navigate(b.dataset.tab);break;
 case 'close':await closeModal();break;
 case 'refresh':await run({type:'refresh'},{quiet:true});break;
 case 'templates':showTemplates();break;
 case 'template':{const [title,category]=templates[Number(b.dataset.index)];showTask(null,{title,category});break}
 case 'task-new':showTask();break;case 'task-edit':showTask(id);break;case 'manage-tasks':manageTasks();break;
 case 'task-toggle':if(await run({type:'task-toggle',id}))reactPet('happy');break;
 case 'task-pause':{let t=s.tasks.find(t=>t.id===id);if(await run({type:'task-save',task:{...t,paused:!t.paused}}))manageTasks();break}
 case 'task-delete':if(confirm('Aufgabe löschen? Bisherige Erfolge bleiben erhalten.')){const t=s.tasks.find(t=>t.id===id);if(await run({type:'task-save',task:{...t,archived:true}}))await closeModal()}break;
 case 'customize':showCustom();break;
 case 'custom-choice':{const form=b.closest('form');form.elements[b.dataset.name].value=b.dataset.value;preview(form);break}
 case 'pet':dialog('Zeit mit '+e(s.profile.petName),`${scene(s)}<div class="row wrap">${[['happy','Streicheln'],['eat','Ein Beerenhäppchen'],['play','Zusammen spielen'],['sleep','Schlummern'],['walk','Eine Runde laufen']].map(([value,label])=>btn(label,'pet-action',`data-value="${value}"`,'small')).join('')}</div><p class="help">Dein Begleiter bleibt auch an Pausentagen gern bei dir. Essen und Spielen verbrauchen keine Münzen.</p>`,'pet');break;
 case 'pet-action':reactPet(b.dataset.value);break;
 case 'mood':showMood(Number(b.dataset.value)||undefined);break;
 case 'mood-choice':{const form=b.closest('form');form.elements.value.value=b.dataset.value;for(const button of form.querySelectorAll('[data-action="mood-choice"]')){let selected=button===b;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))}break}
 case 'travel-start':await run({type:'travel-start',destination:id});break;
 case 'travel-claim':await run({type:'travel-claim',id,choice:Number(b.dataset.choice)});break;
 case 'shop-mode':shopMode=b.dataset.mode;render();break;
 case 'item':showItem(id);break;
 case 'buy':if(await run({type:'buy',id}))showItem(id);break;
 case 'equip':if(await run({type:'equip',id}))await closeModal();break;
 case 'unequip':if(await run({type:'unequip',slot:b.dataset.slot}))await closeModal();break;
 case 'journal-new':journalEditor(null,kind||'journal');break;case 'journal-edit':journalEditor(id);break;case 'journal-list':journalList();break;
 case 'journal-delete':if(confirm('Diesen persönlichen Eintrag dauerhaft löschen?'))if(await run({type:'journal-delete',id}))journalList();break;
 case 'prompt':{const form=b.closest('form'),prompt=prompts[Math.floor(Math.random()*prompts.length)];form.elements.prompt.value=prompt;modal.querySelector('#journal-prompt').textContent=prompt;modal.querySelector('#journal-prompt').classList.remove('hidden');break}
 case 'practice':showPractice(kind);break;
 case 'session-pause':{const t=s.sessions.find(t=>t.id===id);if(await run({type:t.remaining===null?'session-pause':'session-resume',id},{quiet:true}))showPractice(t.kind);break}
 case 'session-finish':if(await run({type:'session-finish',id}))await closeModal();break;
 case 'session-cancel':if(await run({type:'session-cancel',id},{quiet:true}))showPractice(modalData.kind);break;
 case 'relax':showRelax(Number(b.dataset.index));break;
 case 'relax-next':{const index=Number(b.dataset.index),step=Number(b.dataset.step);if(step===relaxations[index].steps.length-1){if(await run({type:'relax'}))await closeModal()}else showRelax(index,step+1);break}
 case 'relax-back':showRelax(Number(b.dataset.index),Number(b.dataset.step)-1);break;
 case 'goals':goals();break;case 'goal-new':goalEditor();break;case 'goal-edit':goalEditor(id);break;
 case 'goal-delete':if(confirm('Dieses Wochenziel entfernen?'))if(await run({type:'goal-delete',id}))goals();break;
 case 'month':{let d=dateOf(month+'-01');d.setMonth(d.getMonth()+Number(b.dataset.delta));month=day(d).slice(0,7);render();break}
 case 'select-day':selectedDay=b.dataset.day;render();break;case 'range':range=Number(b.dataset.range);render();break;
 case 'ledger':ledger();break;case 'install':installHelp();break;
 case 'export':download(backup(s),'Mooslicht-Sicherung-'+day()+'.json');notify('Deine Sicherung wird heruntergeladen. Bewahre sie gut auf.');break;
 case 'import':document.querySelector('#backup-file').click();break;
 case 'persist':{const allowed=await navigator.storage?.persist?.();document.querySelector('#storage-state').textContent=allowed?'Dauerhafte Speicherung wurde vom Browser erlaubt.':'Der Browser konnte dauerhafte Speicherung nicht zusagen. Deine Sicherungsdatei schützt dich zusätzlich.';break}
 case 'calendar-export':calendarExport(s.tasks.find(t=>t.id===id));break;
 case 'reset':if(confirm('Wirklich alle lokalen Mooslicht-Daten löschen? Sichere vorher deinen Spielstand. Dies lässt sich ohne Sicherungsdatei nicht rückgängig machen.')){if(await run({type:'reset'})){modal.close();tab='home';render()}}break;
 case 'update':if(confirm('Neue Version laden? Nicht gespeicherte Formulare werden geschlossen.')){activatingUpdate=true;registration?.waiting?.postMessage('ACTIVATE_UPDATE')}break;
 case 'raw-export':download(JSON.stringify(await rawState(),null,2),'Mooslicht-Originaldaten.json');break;
 case 'retry':await start();break;
 }}catch(error){notify(error.message)}
});
document.addEventListener('input',event=>{if(event.target.name==='journalSearch'){journalSearch=event.target.value;modal.querySelector('#journal-entries').innerHTML=journalEntries();return}const form=event.target.closest('form');if(form&&['onboard','customize'].includes(form.dataset.form))preview(form)});
document.addEventListener('change',async event=>{
 const x=event.target;if(x.matches('[data-rule]'))modal.querySelector('#weekday-field').classList.toggle('hidden',!['weekly','weekdays'].includes(x.value));
 if(x.dataset.filter==='shop'){shopSlot=x.value;render()}if(x.dataset.filter==='tasks'){taskCategory=x.value;manageTasks()}if(x.dataset.filter==='journal'){journalFilter=x.value;journalList()}
 if(x.id==='backup-file'&&x.files[0]){try{const file=x.files[0];if(file.size>15000000)throw Error('Diese Sicherung ist zu groß.');const raw=await file.text();const {parseBackup}=await import('./core.js');const imported=parseBackup(raw);if(confirm(`Sicherung für ${imported.profile.petName} mit ${imported.tasks.length} Aufgaben wiederherstellen? Der aktuelle lokale Spielstand wird ersetzt. Sichere ihn vorher bei Bedarf.`)){const result=await restore(raw);s=result.state;channel?.postMessage(s.revision);render();notify(result.message)}}catch(error){notify(error.message)}finally{x.value=''}}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.dataset.form)return;event.preventDefault();const f=new FormData(form);let ok=false;const val=k=>String(f.get(k)||'');
 switch(form.dataset.form){
 case 'onboard':case 'customize':{let profile={...s.profile};for(const key of ['petName','kind','color','pattern','theme'])profile[key]=val(key);if(form.dataset.form==='onboard')profile.userName=val('userName');profile.petName=profile.petName.trim();ok=await run({type:form.dataset.form==='onboard'?'onboard':'profile',profile});if(ok&&modal.open)await closeModal();break}
 case 'settings':ok=await run({type:'profile',profile:{userName:val('userName').trim(),appearance:val('appearance')}});break;
 case 'task':{const previous=s.tasks.find(t=>t.id===form.dataset.id);ok=await run({type:'task-save',task:{id:form.dataset.id,title:val('title'),category:val('category'),rule:val('rule'),priority:Number(f.get('priority')),startsOn:val('startsOn'),weekdays:f.getAll('weekday').map(Number),time:val('time'),reminder:f.has('reminder'),paused:f.has('paused'),archived:previous?.archived||false}});if(ok)await closeModal();break}
 case 'mood':ok=await run({type:'mood',value:Number(f.get('value')),emotions:f.getAll('emotion')});if(ok)await closeModal();break;
 case 'journal':ok=await run({type:'journal-save',entry:{id:form.dataset.id,kind:val('kind'),prompt:val('prompt'),text:val('text')}});if(ok)journalList();break;
 case 'practice':ok=await run({type:'session-start',kind:form.dataset.kind,seconds:Number(f.get('minutes'))*60},{quiet:true});if(ok)showPractice(form.dataset.kind);break;
 case 'goal':ok=await run({type:'goal-save',goal:{id:form.dataset.id,title:val('title'),category:val('category'),target:Number(f.get('target'))}});if(ok)goals();break;
 }
});
let reaction;
function reactPet(action){clearTimeout(reaction);for(const el of document.querySelectorAll('.scene-pet .pet'))el.setAttribute('class',`pet action-${action} pet-${s.profile.kind}`);reaction=setTimeout(()=>{for(const el of document.querySelectorAll('.scene-pet .pet'))el.setAttribute('class',`pet action-idle pet-${s.profile.kind}`)},4000)}
function formatTime(ms){let seconds=Math.ceil(Math.max(0,ms)/1000);return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function tick(){if(!s)return;const now=Date.now();for(const el of document.querySelectorAll('[data-session-time]')){const t=s.sessions.find(t=>t.id===el.dataset.sessionTime);if(!t)continue;const remaining=t.remaining??Math.max(0,t.end-now);el.textContent=formatTime(remaining);const label=modal.querySelector('[data-phase]');if(label)label.textContent=remaining<=0?'Geschafft':t.remaining!==null?'Pause':t.kind==='focus'?'Deine Fokuszeit':((t.duration-remaining)%10000<4000?'Einatmen':'Ausatmen');modal.querySelector('[data-session-pause]')?.classList.toggle('hidden',remaining<=0);modal.querySelector('[data-session-finish]')?.classList.toggle('hidden',remaining>0)}for(const el of document.querySelectorAll('[data-trip-time]')){const t=s.adventures.find(t=>t.id===el.dataset.tripTime);if(t){el.textContent=t.end<=now?'Deine Geschichte ist bereit':formatTime(t.end-now);document.querySelector('[data-trip-ready]')?.classList.toggle('hidden',t.end>now)}}for(const el of document.querySelectorAll('[data-trip-progress]')){const t=s.adventures.find(t=>t.id===el.dataset.tripProgress);if(t)el.innerHTML=progress(now-t.start,t.end-t.start,'Reisefortschritt')}}
const announced=new Set();
setInterval(async()=>{tick();if(s?.profile.onboarded&&!document.hidden){if(s.lastDay!==day()&&!busy)await run({type:'refresh'},{quiet:true});const now=new Date(),time=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');for(const t of s.tasks.filter(t=>t.reminder&&t.time===time&&!t.paused&&!t.archived)){const o=s.occurrences.find(o=>o.taskID===t.id&&o.day===day()&&!o.done);if(o&&!announced.has(o.id)){announced.add(o.id);notify('Ein kleiner Moment für dich wartet: '+t.title)}}}},1000);
async function pauseBreath(){const t=s?.sessions.find(t=>t.kind==='breathing'&&!t.finished&&t.remaining===null);if(t){await run({type:'session-pause',id:t.id},{quiet:true});if(modalType==='timer'&&modalData.kind==='breathing')showPractice('breathing')}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseBreath();else if(s)run({type:'refresh'},{quiet:true})});
modal.addEventListener('cancel',event=>{event.preventDefault();closeModal()});modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const el=document.querySelector('#connection');if(el)el.textContent=navigator.onLine?'Auf diesem Gerät gespeichert':'Offline · dein Zuhause bleibt bei dir'});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(s)appearance()});
async function start(){try{const result=await transact({type:'recover'});s=result.state;render()}catch(error){app.innerHTML=`<main class="card stack recovery"><h1>Deine Daten bleiben erhalten.</h1><p>Der lokale Spielstand konnte nicht geöffnet werden. Es wurde nichts zurückgesetzt.</p><p class="notice">${e(error.message)}</p>${btn('Originaldaten herunterladen','raw-export')}${btn('Erneut versuchen','retry','','primary')}${btn('Bewusst neu beginnen','reset','','danger')}</main>`}}
await start();
if('serviceWorker' in navigator){try{registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});const ready=await navigator.serviceWorker.ready;installed=!!ready.active;if(modalType==='install')installHelp();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller&&s.profile.onboarded)render()})});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(activatingUpdate)location.reload();else installed=true})}catch{notify('Offline-Dateien konnten noch nicht vorbereitet werden. Bitte lade die App online erneut.')}}
